    var v, Max int32;
    var D word;
    for  v = 0; v < nVars; v++  {
        if Max = Abc_MaxInt(Lms_DelayGet(D1, v), Lms_DelayGet(D2, v)) {
            Lms_DelaySet( &D, v, Abc_MinInt(Max + 1, 15) ); }
    }
    return D;
}

