    var v int32;
    var D word;
    for  v = 0; v < nVars; v++  {
        if Lms_DelayGet(D1, v) != 0 {
            Lms_DelaySet( &D, v, Lms_DelayGet(D1, v) - 1 ); }
    }
    return D;
}

