        } else if Gia_ObjIsCo(pObj) {
            Vec_WrdPush( vDelays, Lms_DelayDecrement( Vec_WrdEntry(vDelays, Gia_ObjFaninId0(pObj, i)), Gia_ManCiNum(p) ) );
        } else if Gia_ObjIsCi(pObj) {
