    for  i = 0; i < nLeaves; i++  {
        pLeaf     = If_ManObj(p, (pCut).pLeaves[int32(pCanonPerm[i])]);
        delayTemp = If_ObjCutBest(pLeaf).Delay + Lms_DelayGet(DelayProfile, i);
        delayMax  = Abc_MaxInt( delayMax, delayTemp );
    }
    return delayMax;
}

