    vDelays        *Vec_Wrd_t;      // pin-to-pin delays of each PO
    vAreas        *Vec_Str_t;       // number of AND gates in each PO
    vFreqs        *Vec_Int_t;       // subgraph usage frequencies
    vTruthFreqs        *Vec_Int_t;  // truth table usage frequencies
    // temporaries
