    nFilterError               int32;
    nFilterSame               int32;
    nAdded               int32;
    nAddedFuncs               int32;
    nHoleInTheWall               int32;
    // runtime
    timeTruth           abctime;
    timeCanon           abctime;
    timeBuild           abctime;
    timeCheck           abctime;
    timeInsert           abctime;
    timeOther           abctime;
    timeTotal           abctime;
}

